import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        int threshold = s.nextInt(), n = s.nextInt();
        TreeMap<String, String> hits = new TreeMap<>();
        for (int i = 0; i < n; i++) {
            String name = s.next();
            int days = s.nextInt();
            if (days < 0) hits.put(name, "EXPIRED");
            else if (days <= threshold) hits.put(name, "ROTATE");
        }
        if (hits.isEmpty()) System.out.println("ALL_OK");
        else hits.forEach((k, v) -> System.out.println(k + " " + v));
    }
}

