import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        int major = s.nextInt(), minor = s.nextInt(), n = s.nextInt();
        Set<String> breaking = Set.of("remove", "make-required", "change-meaning");
        boolean hasBreaking = false, hasCompatible = false;
        for (int i = 0; i < n; i++) {
            String kind = s.next();
            if (breaking.contains(kind)) {
                hasBreaking = true;
                System.out.println(kind + " BREAKING");
            } else {
                hasCompatible = true;
                System.out.println(kind + " COMPATIBLE");
            }
        }
        if (hasBreaking) {
            major++;
            minor = 0;
        } else if (hasCompatible) minor++;
        System.out.println("NEXT " + major + "." + minor);
    }
}
